// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// --- Helpers for the brick-collision defect suite --------------------------

// A single live brick, 20 pts, at the given top-left corner.
function brick(x, y) {
  return { x, y, w: BRICK_W, h: BRICK_H, alive: true, row: 0, points: 20 };
}

// A state with a controlled ball and a controlled brick list.
function setup({ level = 1, ball, bricks }) {
  const state = createState(level);
  if (ball) Object.assign(state.ball, ball);
  if (bricks) state.bricks = bricks;
  return state;
}

// --- Defect 1 — no brick bounce at all (the reported symptom) --------------
// The ball arrives on the top face of a brick (vy > 0, y + r > brick.y) and
// must leave it with vy < 0, having destroyed the brick and scored.
// Today: frame() only kills the brick; step() never deflects the ball.

test('bricks: ball hitting a top face bounces up, kills the brick, scores', () => {
  const state = setup({
    ball: { x: 286, y: 90, vx: 0, vy: ballSpeed(1) },
    bricks: [brick(250, 100)],
  });
  step(state, 1 / 20); // 13 px, slow enough that there is no tunneling

  assert.equal(state.bricks[0].alive, false, 'the brick is destroyed');
  assert.equal(Math.sign(state.ball.vy), UP, 'vy flips UP after the bounce');
  assert.ok(
    state.ball.y + BALL_R < 100,
    'the ball is pushed back out of the brick',
  );
  assert.equal(state.combo, 1, 'the brick counts once');
  assert.ok(state.score > 0, 'the brick scores');
});

// --- Defect 2 — sticky contact ---------------------------------------------
// After resolution the ball must be OUTSIDE the brick rectangle; otherwise it
// re-overlaps next frame and re-inverts forever.

test('bricks: overlapping ball is pushed out, never left inside the brick', () => {
  const state = setup({
    // Already 3 px inside the top face of the brick (bad previous frame).
    ball: { x: 286, y: 96, vx: 0, vy: ballSpeed(1) },
    bricks: [brick(250, 100)],
  });
  step(state, 1 / 60);

  assert.equal(
    collides(state.ball, state.bricks[0]),
    false,
    'no residual overlap after resolution',
  );
  assert.equal(Math.sign(state.ball.vy), UP, 'vy flipped once');
});

// --- Defect 3 — seam: double inversion cancels out -------------------------
// A ball landing on the seam between two bricks touches both. Two naive
// vy = -vy (one per brick) cancel each other and the ball keeps going down.
// Expected: one bounce per pass (vy flips exactly once), both bricks die.

test('bricks: seam hit kills both bricks with a single bounce', () => {
  const state = setup({
    ball: { x: 326, y: 92.5, vx: 0, vy: ballSpeed(1) }, // dead center of the gap
    bricks: [brick(250, 100), brick(330, 100)], // gap [322, 330]
  });
  step(state, 1 / 20);

  assert.ok(
    state.bricks.every((b) => !b.alive),
    'both seam bricks are destroyed',
  );
  assert.equal(Math.sign(state.ball.vy), UP, 'vy flipped exactly once');
  assert.ok(
    state.ball.y + BALL_R <= 100,
    'the ball is above both bricks after the bounce',
  );
  assert.equal(state.combo, 2, 'each brick counted once');
});

// --- Defect 4 — face vs corner ---------------------------------------------
// The hit axis is the face of smallest penetration. A pure side hit flips vx
// and leaves vy alone; an exact corner hit flips both.

test('bricks: side face hit flips vx, keeps vy', () => {
  const state = setup({
    ball: { x: 236, y: 110, vx: 300, vy: 0 }, // approaching the left face
    bricks: [brick(250, 100)],
  });
  step(state, 1 / 20);

  assert.ok(state.ball.vx < 0, 'vx flipped LEFT');
  assert.equal(state.ball.vy, 0, 'vy untouched by a side hit');
  assert.ok(
    state.ball.x + BALL_R < 250,
    'the ball is pushed back out of the left face',
  );
  assert.equal(
    Math.hypot(state.ball.vx, state.ball.vy),
    ballSpeed(1),
    'speed after the bounce is the level speed',
  );
});

test('bricks: exact corner hit flips both components', () => {
  const state = setup({
    // 45° descent aimed exactly at the top-left corner (equal penetrations).
    ball: { x: 233, y: 83, vx: 300, vy: 300 },
    bricks: [brick(250, 100)],
  });
  step(state, 1 / 20);

  assert.ok(state.ball.vx < 0, 'vx flipped LEFT');
  assert.ok(state.ball.vy < 0, 'vy flipped UP');
  assert.equal(collides(state.ball, state.bricks[0]), false, 'out of the brick');
});

// --- Defect 5 — tunneling --------------------------------------------------
// Max step at level 6: ballSpeed(6) * 0.05 = 710 * 0.05 = 35.5 px, which is
// larger than brick height 20 + ball diameter 14 = 34 px. The ball crosses the
// whole brick between two frames; only a swept test catches it.

test('bricks: fast ball (level 6) cannot tunnel through a brick', () => {
  const state = setup({
    level: 6,
    ball: { x: 286, y: 92.5, vx: 0, vy: ballSpeed(6) },
    bricks: [brick(250, 100)],
  });
  step(state, 0.05); // 35.5 px in one frame — past the whole brick

  assert.equal(state.bricks[0].alive, false, 'the brick is still hit');
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball bounces, not plows');
  assert.ok(state.ball.y + BALL_R < 100, 'the ball is above the brick');
});

// --- Defect 6 — paddle: tunneling and the teleported paddle ----------------
// The paddle capture zone is PADDLE_H = 12 px tall, smaller than the level-6
// step (35.5 px): the ball can skip over it. Expected: the ball always exits
// through the top of the paddle, even when the paddle teleports onto it.

test('paddle: fast ball crossing the paddle plane still bounces out the top', () => {
  const state = setup({
    level: 6,
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 0.5, vx: 0, vy: ballSpeed(6) },
    bricks: [],
  });
  const lost = step(state, 0.05); // 35.5 px — the whole paddle zone

  assert.equal(lost, false, 'the ball is not lost');
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball bounced off the paddle');
  assert.ok(
    state.ball.y + BALL_R < PADDLE_Y,
    'the ball exits through the top of the paddle',
  );
});

test('paddle: paddle teleported onto the ball never traps it', () => {
  const state = setup({
    ball: { x: WIDTH / 2, y: PADDLE_Y + PADDLE_H / 2, vx: 0, vy: 300 },
    bricks: [],
  });
  step(state, 1 / 60);

  assert.equal(Math.sign(state.ball.vy), UP, 'the ball is bounced out');
  assert.ok(
    state.ball.y + BALL_R < PADDLE_Y,
    'the ball comes back out through the top',
  );
});

// --- Defect 7 — speed norm is not conserved --------------------------------
// After ANY bounce the speed must be ballSpeed(level). Today the paddle
// bounce replaces vx without rescaling vy, and the brick bounce does not
// exist at all.

test('speed: paddle bounce preserves the level speed', () => {
  const state = setup({
    ball: { x: WIDTH / 2 - 24, y: PADDLE_Y - BALL_R - 2, vx: 0, vy: 300 }, // |v| = 300 ≠ 260
    bricks: [],
  });
  step(state, 1 / 60);

  assert.ok(Math.sign(state.ball.vy) === UP, 'bounced');
  assert.equal(
    Math.hypot(state.ball.vx, state.ball.vy),
    ballSpeed(1),
    '|v| after the paddle bounce equals ballSpeed(1)',
  );
});

test('speed: brick bounce rescales to the level speed', () => {
  const state = setup({
    ball: { x: 286, y: 90, vx: 100, vy: 300 }, // |v| = 316 ≠ 260
    bricks: [brick(250, 100)],
  });
  step(state, 1 / 60);

  assert.equal(Math.sign(state.ball.vy), UP, 'bounced');
  assert.equal(
    Math.hypot(state.ball.vx, state.ball.vy),
    ballSpeed(1),
    '|v| after the brick bounce equals ballSpeed(1)',
  );
});

// --- Defect 8 — dead angle -------------------------------------------------
// A perfect center hit on the paddle gives hit = 0, so vx = 0 and the ball
// oscillates vertically forever. Every trajectory must stay playable.

test('angle: dead-center paddle hit keeps a horizontal component', () => {
  const state = setup({
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, vx: 0, vy: 300 },
    bricks: [],
  });
  step(state, 1 / 60);

  assert.ok(Math.abs(state.ball.vx) > 0, 'vx must not be zero');
  assert.equal(
    Math.hypot(state.ball.vx, state.ball.vy),
    ballSpeed(1),
    'still at the level speed',
  );
});

// --- Defect 9 — dependency on dt -------------------------------------------
// The same trajectory must give the same result at 30 fps and at 144 fps:
// same brick destroyed, same bounce, same final state. Only a swept
// (continuous) collision can guarantee that.

test('dt: 30 fps and 144 fps give the same bounce outcome', () => {
  const brickPos = { x: 250, y: 100 };

  function run(dt) {
    const state = setup({
      level: 6,
      ball: { x: 286, y: 20, vx: 0, vy: ballSpeed(6) },
      bricks: [brick(brickPos.x, brickPos.y)],
    });
    for (let frame = 0; frame < 200; frame++) {
      if (Math.sign(state.ball.vy) === UP) {
        return {
          x: state.ball.x,
          y: state.ball.y,
          vx: state.ball.vx,
          vy: state.ball.vy,
          brickAlive: state.bricks[0].alive,
        };
      }
      if (step(state, dt)) break; // ball lost: no bounce ever happened
    }
    return null; // no bounce within the horizon
  }

  const at30 = run(1 / 30);
  const at144 = run(1 / 144);
  assert.notEqual(at30, null, 'the ball bounces at 30 fps');
  assert.notEqual(at144, null, 'the ball bounces at 144 fps');
  assert.deepEqual(at144, at30, 'identical outcome whatever the frame rate');
});

