test('dt: 30 fps and 144 fps give the same bounce outcome', () => {
  const brickY = 100;

  function run(dt) {
    const state = setup({
      level: 6,
      ball: { x: 286, y: 20, vx: 0, vy: ballSpeed(6) },
      bricks: [brick(250, brickY)],
    });
    for (let frame = 0; frame < 200; frame++) {
      const vyBefore = state.ball.vy;
      const lost = step(state, dt);
      if (state.ball.vy < 0 && vyBefore > 0) {
        // The ball bounced during this step: capture the outcome.
        return {
          x: state.ball.x,
          y: state.ball.y,
          vx: state.ball.vx,
          vy: state.ball.vy,
          brickAlive: state.bricks[0].alive,
        };
      }
      if (lost) return null; // lost before any bounce
      // Below the brick with vy still pointing down: the brick was skipped.
      if (state.ball.y - BALL_R > brickY + BRICK_H) return null;
    }
    return null; // no bounce within the horizon
  }

