    // corner: both components flip, the ball is pushed diagonally out
    ball.x = dx > 0 ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = dy > 0 ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  }

  normalizeSpeed(state);
  return true;
}
