// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// The ball is pushed EPS beyond the face it touched, so it can never
// re-collide on the very next frame (no sticky contact).
const EPS = 1e-3;

// The paddle rebound offset is clamped so a dead-center hit (offset 0) cannot
// turn the trajectory into a pure vertical oscillation (dead angle).
const MIN_PADDLE_HIT = 0.2;

// Rescales the ball velocity so that |v| equals ballSpeed(level). Every
// bounce (wall, ceiling, paddle, brick) must leave the ball at the level
// speed, whatever the incoming speed was (norm conservation).
function normalizeSpeed(state) {
  const speed = ballSpeed(state.level);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  if (norm > 0) {
    state.ball.vx *= speed / norm;
    state.ball.vy *= speed / norm;
  }
}

// Swept circle-vs-brick detection. The ball (radius r) travels the segment
// [x0,y0] → [x1,y1] during the frame; treat it as a point moving against the
// brick AABB expanded by r (Minkowski sum). Returns the first entry into the
// expanded box, with the face that was crossed:
//   t     — fraction of the frame at entry (0 = already overlapping)
//   axis  — 'x' (side face), 'y' (top/bottom face) or 'corner' (both at once)
//   x, y  — ball center at the entry point
// Because the whole segment is tested, a step longer than the brick still
// reports a hit: no tunneling.
function sweepEntry(ball, x0, y0, x1, y1, brick) {
  const xmin = brick.x - ball.r;
  const xmax = brick.x + brick.w + ball.r;
  const ymin = brick.y - ball.r;
  const ymax = brick.y + brick.h + ball.r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tx0, tx1, ty0, ty1;
  if (dx === 0) {
    if (x0 < xmin || x0 > xmax) return null; // parallel, never enters
    tx0 = -Infinity;
    tx1 = Infinity;
  } else {
    tx0 = (xmin - x0) / dx;
    tx1 = (xmax - x0) / dx;
    if (tx0 > tx1) {
      const t = tx0;
      tx0 = tx1;
      tx1 = t;
    }
  }
  if (dy === 0) {
    if (y0 < ymin || y0 > ymax) return null;
    ty0 = -Infinity;
    ty1 = Infinity;
  } else {
    ty0 = (ymin - y0) / dy;
    ty1 = (ymax - y0) / dy;
    if (ty0 > ty1) {
      const t = ty0;
      ty0 = ty1;
      ty1 = t;
    }
  }

  const tIn = Math.max(tx0, ty0, 0);
  const tOut = Math.min(tx1, ty1, 1);
  if (tIn > tOut) return null;

  // The face entered last (largest slab entry) is the one that was hit; equal
  // entries mean the ball went through a corner (both components flip).
  const axis = Math.abs(tx0 - ty0) < 1e-9 ? 'corner' : tx0 > ty0 ? 'x' : 'y';
  return { t: tIn, axis, x: x0 + dx * tIn, y: y0 + dy * tIn };
}

// Brick collision for one frame step: the ball traveled from (x0,y0) to its
// current position. Returns `true` if a bounce happened.
//
// Rules enforced here:
//  - swept detection: a fast ball cannot cross a brick between two frames;
//  - ONE bounce per pass: a seam hit between two bricks kills both but flips
//    the velocity once (two flips would cancel out and the ball would plow
//    through);
//  - the ball is pushed back out of the face(s) it entered, so it never
//    re-collides on the next frame;
//  - the hit axis is the face of smallest penetration; an exact corner flips
//    both components;
//  - the speed after the bounce is ballSpeed(level).
export function bounceBricks(state, x0, y0) {
  const { ball } = state;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweepEntry(ball, x0, y0, ball.x, ball.y, brick);
    if (hit) hits.push({ brick, hit });
  }
  if (hits.length === 0) return false;

  const tMin = Math.min(...hits.map((h) => h.hit.t));
  const first = hits.find((h) => Math.abs(h.hit.t - tMin) < 1e-9);
  const { brick: firstBrick, hit } = first;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  // Kill and score every brick entered at the same instant (seam hits).
  for (const { brick: b, hit: h } of hits) {
    if (Math.abs(h.t - tMin) > 1e-9) continue;
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }

  // One bounce for the whole pass, on the axis of the first hit.
  if (hit.axis === 'x' || hit.axis === 'corner') ball.vx = -ball.vx;
  if (hit.axis === 'y' || hit.axis === 'corner') ball.vy = -ball.vy;

  // Push the ball back out of the face(s) it entered (anti-sticky contact).
  if (hit.axis === 'x') {
    ball.x =
      dx > 0 ? firstBrick.x - ball.r - EPS : firstBrick.x + firstBrick.w + ball.r + EPS;
    ball.y = hit.y;
  } else if (hit.axis === 'y') {
    ball.x = hit.x;
    ball.y =
      dy > 0 ? firstBrick.y - ball.r - EPS : firstBrick.y + firstBrick.h + ball.r + EPS;
  } else {
    // corner: pushed diagonally out of the corner it entered
    ball.x =
      dx > 0 ? firstBrick.x - ball.r - EPS : firstBrick.x + firstBrick.w + ball.r + EPS;
    ball.y =
      dy > 0 ? firstBrick.y - ball.r - EPS : firstBrick.y + firstBrick.h + ball.r + EPS;
  }

  normalizeSpeed(state);
  return true;
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the bricks and the paddle. Brick collision is swept
// (continuous) so the result does not depend on the frame rate, and the paddle
// test is swept too so a fast ball cannot skip the capture zone.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const x0 = ball.x; // position at the start of the frame, for the sweeps
  const y0 = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
    normalizeSpeed(state);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
    normalizeSpeed(state);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
    normalizeSpeed(state);
  }

  // Bricks (swept collision along the path traveled this frame).
  bounceBricks(state, x0, y0);

  // Paddle: swept, so the ball always exits through the top — whether it
  // crossed the capture plane between two frames (tunneling) or the paddle was
  // teleported under it by the mouse (trapped ball).
  if (ball.vy > 0) {
    const top = paddle.y - ball.r;
    const bottom = paddle.y + paddle.h + ball.r;
    const crossed = y0 <= top && ball.y >= top; // top plane crossed this frame
    const trapped = ball.y >= top && ball.y <= bottom; // already inside the slab
    if (crossed || trapped) {
      // Horizontal position at the crossing (for the swept case).
      let cx = ball.x;
      if (crossed && ball.y !== y0) {
        const t = (top - y0) / (ball.y - y0);
        cx = x0 + (ball.x - x0) * t;
      }
      if (cx >= paddle.x - ball.r && cx <= paddle.x + paddle.w + ball.r) {
        ball.x = cx;
        ball.y = top - EPS;
        ball.vy = -Math.abs(ball.vy);
        // The rebound angle depends on where the paddle was hit; the offset is
        // clamped so a dead-center hit keeps a horizontal component (no dead
        // angle) and vy is derived from the level speed (norm conserved).
        const raw = (cx - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
        const bounded = Math.max(-1, Math.min(1, raw));
        const hit =
          Math.abs(bounded) < MIN_PADDLE_HIT
            ? Math.sign(bounded || 1) * MIN_PADDLE_HIT
            : bounded;
        const speed = ballSpeed(state.level);
        ball.vx = speed * 0.6 * hit;
        ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
        state.combo = 0; // touching the paddle resets the combo
      }
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

